import React from 'react';

export default function SummarizeSection({ originalText, summary, setSummary }) {
  // Placeholder: implement API call to backend for summarization
  return (
    <div>
      <h2 className="font-bold mb-2">Summary</h2>
      <textarea className="w-full h-32 p-2 border rounded" value={summary} readOnly />
      <div className="text-sm text-gray-500 mt-2">(Summary will appear here)</div>
    </div>
  );
}
